import { Mongo } from 'meteor/mongo';

export const WifiClientModeState = new Mongo.Collection('wifiClientModeState');

if (Meteor.isServer) {
	Meteor.publish('wifiClientModeState', function wifiClientModeStatePublication() {
		return WifiClientModeState.find({ _id: 'wifi-client-mode-state' });
	});
}
